pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address token, address sender, address recipient, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(recipient != address(0));
        vm.assume(token != address(0));
        vm.assume(amount > 0);
        vm.assume(token != address(c));

        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint256[] memory vs = new uint256[](1);
        vs[0] = amount;

        vm.prank(sender);
        try c.transfer(token, tos, vs) returns (bool ok) {
            // call succeeded
        } catch {
            // call reverted
        }

        // After the call, the external token's allowance of c from the sender must not have decreased
        // because the reference contract calls transferFrom(msg.sender,...) and the mutant calls transfer(...)
        // which transfers from c itself.
        // We assert that c's own balance of the token is unchanged (no tokens were moved from c).
        // The reference passes because it never moves c's tokens. The mutant will move tokens from c if c has balance.
        //
        // Using a mock token helper to observe the calls and track state changes.
        // Deploy a token mock that captures sender.
        TokenMock mock = new TokenMock();
        // For the assertion, we check that no transferFrom(c,...) was called.
        // Actually, we use a different approach: check that c did not lose tokens.
        // Deploy mock, give c tokens.
        mock.mint(address(c), amount);
        vm.prank(address(c));
        mock.approve(token, amount);

        address[] memory tos2 = new address[](1);
        tos2[0] = recipient;
        uint256[] memory vs2 = new uint256[](1);
        vs2[0] = amount;

        uint256 cBalanceBefore = mock.balanceOf(address(c));
        vm.prank(sender);
        try c.transfer(address(mock), tos2, vs2) returns (bool ok2) {
            // call succeeded
        } catch {
            // call reverted
        }
        uint256 cBalanceAfter = mock.balanceOf(address(c));

        // The reference contract calls transferFrom(msg.sender, to, amount) so c balance should not change.
        // The mutant calls transfer(to, amount) using c as caller, deducting from c.
        assertEq(cBalanceBefore, cBalanceAfter, "C balance changed - mutant moved tokens from C");
    }
}

contract TokenMock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        require(balanceOf[from] >= amount, "insufficient balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

