pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address contract_address, address[] calldata tos, uint[] calldata vs) public {
        // admissible domain: equal non-zero lengths; contract_address not zero and not c itself
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // Deploy a helper that always succeeds on transferFrom, enabling observation of loop iteration count
        Helper helper = new Helper();
        address helperAddr = address(helper);

        // Drive c through transfer using the helper as the contract_address
        // The helper records how many times transferFrom was called
        bool success;
        try c.transfer(helperAddr, tos, vs) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }

        // Property: success must be true and exactly tos.length calls made (the correct contract iterates over tos.length)
        assertTrue(success && helper.callCount() == tos.length);
    }
}

contract Helper {
    uint public callCount;

    // Minimal transferFrom that always succeeds and increments callCount
    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }
}

