pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        RevertingTransferHelper helper = new RevertingTransferHelper();
        // Call transfer using the helper as the contract_address; the helper reverts on the first callback,
        // so the original loop would call exactly once and succeed (since the require is inside the call),
        // but the mutant may iterate differently and try to access out-of-bounds tos[i] before the call reverts.
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, address(helper), tos, vs));
        // Both versions will revert in this scenario; the property is that the call should NOT succeed.
        // In the reference, no out-of-bounds access occurs regardless of loop bounds; the mutant may access
        // tos[i] with i >= tos.length, causing a different revert reason or silent revert.
        // We assert that the call always fails.
        assertTrue(!ok);
    }
}

contract RevertingTransferHelper {
    bytes4 internal constant TRANSFER_FROM_SELECTOR = bytes4(keccak256("transferFrom(address,address,uint256)"));
    fallback() external payable {
        if (msg.sig == TRANSFER_FROM_SELECTOR && msg.data.length >= 4) {
            revert();
        }
    }
}

