pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        // Deploy a reverter contract that makes the external call fail.
        Reverter reverter = new Reverter();
        // Replace the contract_address with the reverter so the external call will revert.
        contract_address = address(reverter);
        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        // The reference must revert because the external call fails, so ok must be false.
        // The mutant succeeds (returns true) even when the external call fails, so ok would be true for the mutant.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
